<?php require_once __DIR__.'/../config/config.php';require_admin();$pageTitle='Activity logs';$active='activity';$rows=[];try{$rows=$pdo->query('SELECT admin_email,action,details,created_at FROM admin_activity ORDER BY created_at DESC LIMIT 500')->fetchAll();}catch(Throwable $e){}require __DIR__.'/_layout.php';?><section class="welcome-row"><div><p class="eyebrow">AUDIT TRAIL</p><h1>Studio <em>activity.</em></h1><p class="muted">Recent administrator actions recorded by the application.</p></div></section><section class="panel"><div class="panel-head"><h2><?=count($rows)?> events</h2><input style="max-width:260px" type="search" placeholder="Search logs…" data-search-table="#logs"></div><div class="table-wrap"><table id="logs"><thead><tr><th>ADMIN</th><th>ACTION</th><th>DETAILS</th><th>TIME</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['admin_email'])?></td><td><?=e($r['action'])?></td><td><?=e($r['details']??'')?></td><td><?=e($r['created_at'])?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td class="empty" colspan="4">No activity has been recorded yet.</td></tr><?php endif;?></tbody></table></div></section><?php require __DIR__.'/_footer.php';?>